INSERT [dbo].[Templates] ([TemplateTypeId], [Name], [Active], [Content], [marginLeft], [marginRight], [marginTop], [marginBottom], [SignatureImagePath], [Header]) VALUES (4, N'Disposicion 2018 Jurisdiccional', 1, N'<p style="text-align: justify;">VISTO la Ley de Educaci&oacute;n T&eacute;cnico Profesional N&deg; 26.058, la creaci&oacute;n del FONDO PROVINCIAL del PROGRAMA N&deg;39 para la PROVINCIA DE&nbsp;[JURISDICCION] y el plan de mejora que tramita mediante el Expediente Electr&oacute;nico N&deg;&nbsp;[NRO_EXPEDIENTE] y;</p>
<p style="text-align: justify;">CONSIDERANDO:</p>
<p style="text-align: justify;">Que los objetivos de la Ley N&ordm; 26.058 refieren a la necesidad de alcanzar mayores niveles de equidad, calidad, pertinencia, relevancia y efectividad de la Educaci&oacute;n T&eacute;cnico Profesional (ETP) a trav&eacute;s del fortalecimiento y mejora continua de las instituciones y programas de educaci&oacute;n t&eacute;cnico profesional en el marco de pol&iacute;ticas nacionales y estrategias de car&aacute;cter federal que integren las particularidades y diversidades jurisdiccionales.</p>
<p style="text-align: justify;">Que el Art. N&deg; 52 de la Ley N&deg; 26.058 crea el Fondo Nacional para la Educaci&oacute;n T&eacute;cnico Profesional a fin de garantizar la inversi&oacute;n necesaria para el mejoramiento de la calidad de las instituciones de ETP.</p>
<p style="text-align: justify;">Que mediante la Resoluci&oacute;n N&deg; 283 CONSEJO FEDERAL DE EDUCACI&Oacute;N de fecha 29 de Junio de 2016, se aprueba el documento &ldquo;Mejora Integral de la Calidad de la Educaci&oacute;n T&eacute;cnico Profesional&rdquo;, para la aplicaci&oacute;n de la Ley N&deg; 26.058.</p>
<p style="text-align: justify;">Que para financiar las l&iacute;neas de acci&oacute;n incluidas en la Resoluci&oacute;n antes indicada, se crea el FONDO PROVINCIAL del PROGRAMA N&deg;39 para la PROVINCIA DE [JURISDICCION].</p>
<p style="text-align: justify;">Que el&nbsp;[MINISTERIO_PROVINCIA] present&oacute; los Planes de Mejora de acuerdo a la normativa vigente.</p>
<p style="text-align: justify;">Que la DIRECCI&Oacute;N NACIONAL DE ASUNTOS FEDERALES ha tomado intervenci&oacute;n sobre los proyectos mencionados dictaminando su aprobaci&oacute;n, los cuales ser&aacute;n financiados mediante el FONDO PROVINCIAL del PROGRAMA N&deg;39 de la PROVINCIA DE [JURISDICCION].</p>
<p style="text-align: justify;">Que la presente medida no genera erogaci&oacute;n presupuestaria para el ejercicio financiero vigente.</p>
<p style="text-align: justify;">Que la presente medida se dicta en las facultades conferidas por la Ley 26.058, Decreto 668/17, Decreto 1895/02 y la Resoluci&oacute;n CFE N&ordm; 283 del 29 de Junio de 2016.</p>
<p style="text-align: justify;">Por ello,</p>
<p style="text-align: justify;">EL DIRECTOR EJECUTIVO DEL</p>
<p style="text-align: justify;">INSTITUTO NACIONAL DE EDUCACI&Oacute;N TECNOL&Oacute;GICA</p>
<p style="text-align: justify;">DISPONE:</p>
<p style="text-align: justify;">ARTICULO 1&ordm;.- Aprobar el Plan de mejora de conformidad con el dictamen N&ordm;&nbsp;[NRO_DICTAMEN]&nbsp; detallado en el Anexo (Anexo I) que acompa&ntilde;a la presente disposici&oacute;n.</p>
<p style="text-align: justify;">ARTICULO 2&deg;.- Los dict&aacute;menes aprobados en el ART&Iacute;CULO 1&ordm; ser&aacute; financiado a trav&eacute;s del FONDO PROVINCIAL del PROGRAMA N&deg;39 para la PROVINCIA DE&nbsp;[JURISDICCION] vigente al momento de la ejecuci&oacute;n del mismo.</p>
<p style="text-align: justify;">ART&Iacute;CULO 3&deg;.- Los responsables de la administraci&oacute;n de los recursos deber&aacute;n rendir expresa y documentada cuenta de los fondos de acuerdo con lo establecido en la Resoluci&oacute;n CFE N&deg; 283/16, la Resoluci&oacute;n Ministerial N&deg; 2092/11 y la Resoluci&oacute;n INET N&deg; 701/16, a trav&eacute;s del Sistema de Transferencias de Recursos Educativos (SiTraRed).</p>
<p style="text-align: justify;">ARTICULO 4&ordm;.- Comun&iacute;quese. Cumplido, arch&iacute;vese.</p>', 40, 10, 50, 25, NULL, NULL)
GO